import { test, expect } from "@playwright/test";

test.describe("Product Search", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("http://localhost:3000");
  });

  test("Search bar should be visible", async ({ page }) => {
    const searchBar = page.getByRole("searchbox", { name: /search/i });
    await expect(searchBar).toBeVisible();
  });

  test("Results should appear after search", async ({ page }) => {
    const searchBar = page.getByRole("searchbox", { name: /search/i });
    await searchBar.fill("laptop");
    await page.keyboard.press("Enter");

    const results = page.locator(".search-results, [data-testid='search-results']");
    await expect(results).toBeVisible();
  });

  test("Results should match keyword", async ({ page }) => {
    const searchBar = page.getByRole("searchbox", { name: /search/i });
    const keyword = "phone";

    await searchBar.fill(keyword);
    await page.keyboard.press("Enter");

    const resultItems = page.locator(
      ".product-item, [data-testid='product-item'], li"
    );
    const count = await resultItems.count();

    if (count > 0) {
      const firstResult = resultItems.first();
      const text = await firstResult.textContent();
      expect(text.toLowerCase()).toContain(keyword.toLowerCase());
    } else {
      const noResults = page.locator(
        "text=/no results|no products found/i"
      );
      await expect(noResults).toBeVisible();
    }
  });
});
